import sys
sys.setrecursionlimit(10000)

d = sys.stdin.read().split()
n = int(d[0])
pos = 1
root = {}
for _ in range(n):
    k = int(d[pos])
    cur = root
    for nm in d[pos + 1:pos + 1 + k]:
        cur = cur.setdefault(nm, {})
    pos += 1 + k

def canon(t):
    return tuple(sorted((k, canon(v)) for k, v in t.items()))

cnt = {}
def walk(t):
    for v in t.values():
        c = canon(v)
        if c:
            cnt[c] = cnt.get(c, 0) + 1
        walk(v)
walk(root)

res = []
def out(t, pre):
    for k, v in t.items():
        c = canon(v)
        if c and cnt[c] > 1:
            continue
        res.append(pre + [k])
        out(v, pre + [k])
out(root, [])
res.sort()
print(len(res))
for p in res:
    print('/' + '/'.join(p))

