import java.util.*;
import java.io.*;

public class Main {
    static List<List<String>> deleteDuplicateFolders(List<List<String>> paths) {
        // Write your solution here: return the paths of the remaining folders (any order)
        return new ArrayList<>();
    }

    public static void main(String[] args) throws IOException {
        StringTokenizer st = new StringTokenizer(new String(System.in.readAllBytes()));
        int n = Integer.parseInt(st.nextToken());
        List<List<String>> paths = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            int k = Integer.parseInt(st.nextToken());
            List<String> p = new ArrayList<>();
            for (int j = 0; j < k; j++) p.add(st.nextToken());
            paths.add(p);
        }
        List<List<String>> res = new ArrayList<>(deleteDuplicateFolders(paths));
        res.sort((a, b) -> {
            int m = Math.min(a.size(), b.size());
            for (int i = 0; i < m; i++) {
                int c = a.get(i).compareTo(b.get(i));
                if (c != 0) return c;
            }
            return Integer.compare(a.size(), b.size());
        });
        StringBuilder sb = new StringBuilder();
        sb.append(res.size()).append('\n');
        for (List<String> p : res) {
            for (String name : p) sb.append('/').append(name);
            sb.append('\n');
        }
        System.out.print(sb);
    }
}
